function makeTimeWindow(startHour, endHour) {
  const isValidHour = (h) => typeof h === 'number' && Number.isInteger(h) && h >= 0 && h <= 23;
  if (!isValidHour(startHour) || !isValidHour(endHour)) {
    throw new Error('hours must be integers between 0 and 23');
  }
  if (startHour >= endHour) {
    throw new Error('startHour must be strictly less than endHour');
  }
  return { startHour, endHour };
}

