function createShippingLabel(kind, details) {
  if (kind === 'domestic') {
    if (typeof details.zipCode !== 'string' || details.zipCode.length === 0) {
      throw new Error('domestic label requires a non-empty zipCode');
    }
    return { kind: 'domestic', zipCode: details.zipCode };
  }
  if (kind === 'international') {
    if (typeof details.country !== 'string' || details.country.length === 0) {
      throw new Error('international label requires a non-empty country');
    }
    if (typeof details.customsFee !== 'number' || details.customsFee <= 0) {
      throw new Error('international label requires a positive customsFee');
    }
    return { kind: 'international', country: details.country, customsFee: details.customsFee };
  }
  throw new Error('unknown shipping label kind: ' + kind);
}

