function createSubscriptionPlan(kind, details) {
  if (kind === 'monthly') {
    if (typeof details.priceCents !== 'number' || details.priceCents <= 0) {
      throw new Error('monthly plan requires a positive priceCents');
    }
    return { kind: 'monthly', priceCents: details.priceCents };
  }
  if (kind === 'annual') {
    if (typeof details.priceCents !== 'number' || details.priceCents <= 0) {
      throw new Error('annual plan requires a positive priceCents');
    }
    if (typeof details.discountMonths !== 'number' || !Number.isInteger(details.discountMonths) || details.discountMonths <= 0) {
      throw new Error('annual plan requires a positive integer discountMonths');
    }
    return { kind: 'annual', priceCents: details.priceCents, discountMonths: details.discountMonths };
  }
  throw new Error('unknown subscription plan kind: ' + kind);
}
